$xml=file_get_contents($folder.'/evento-cancelamento.xml');$d=new DOMDocument();$d->loadXML($xml,LIBXML_NONET);libxml_use_internal_errors(true);$valid=$d->schemaValidate('/var/www/html/emissor/api-fiscal/resources/nfse/schemas/1.01-20261020/evento_v1.01.xsd');$errors=array_map(fn($e)=>trim($e->message),libxml_get_errors());libxml_clear_errors();
$x=new DOMXPath($d);$x->registerNamespace('ds','http://www.w3.org/2000/09/xmldsig#');$checks=[];
foreach($x->query('//ds:Signature') as $s){$si=$x->query('ds:SignedInfo',$s)->item(0);$a=$x->evaluate('string(ds:CanonicalizationMethod/@Algorithm)',$si);$cert=$x->evaluate('string(ds:KeyInfo/ds:X509Data/ds:X509Certificate)',$s);$pem="-----BEGIN CERTIFICATE-----\n".chunk_split(preg_replace('/\s+/','',$cert),64,"\n")."-----END CERTIFICATE-----\n";$ok=openssl_verify($si->C14N(str_contains($a,'xml-exc-c14n'),str_contains($a,'WithComments')),base64_decode($x->evaluate('string(ds:SignatureValue)',$s)),openssl_pkey_get_public($pem),OPENSSL_ALGO_SHA256)===1;$id=substr($x->evaluate('string(ds:Reference/@URI)',$si),1);$target=null;foreach($x->query('//*[@Id]') as $n){if($n->getAttribute('Id')===$id){$target=$n;break;}}$ts=$x->query('ds:Reference/ds:Transforms/ds:Transform',$si);$t=$ts->item($ts->length-1)->getAttribute('Algorithm');$hash=$target?base64_encode(hash('sha256',$target->C14N(str_contains($t,'xml-exc-c14n'),str_contains($t,'WithComments')),true)):'';$checks[]=['assinatura_valida'=>$ok,'digest_valido'=>hash_equals($x->evaluate('string(ds:Reference/ds:DigestValue)',$si),$hash)];}
